// Compiles docs/email-templates (base templates + one JSON config per email) into backend/emails.generated.js,
// which backend/mailer.js renders from. The docs folder is the only copy; the generated file is never hand-edited.
//   node scripts/build-emails.mjs            write backend/emails.generated.js
//   node scripts/build-emails.mjs --check    fail if it's stale (part of npm run check)
//   node scripts/build-emails.mjs --previews also render every email with its "sample" values into
//                                            docs/email-templates/previews/ (.html and .txt)
import { readFileSync, writeFileSync, readdirSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = join(import.meta.dirname, '..');
const docs = join(root, 'docs', 'email-templates');
const strip = (html) => html.replace(/\r\n/g, '\n').replace(/<!--(?!\[if)[\s\S]*?-->\n?/g, '').trim();
const read = (path) => readFileSync(join(docs, path), 'utf8');

const LAYOUTS = {};
for (const direction of ['outbound', 'inbound']) {
  LAYOUTS[direction] = { html: strip(read(`base/${direction}.html`)), text: read(`base/${direction}.txt`).replace(/\r\n/g, '\n').trim() };
  for (const [kind, body] of Object.entries(LAYOUTS[direction])) if (!body.includes('{{content}}')) throw Error(`base/${direction}.${kind === 'html' ? 'html' : 'txt'} needs {{content}}`);
}

const EMAILS = {};
const SAMPLES = {};
for (const file of readdirSync(join(docs, 'emails')).filter((f) => f.endsWith('.json')).sort()) {
  const name = file.replace(/\.json$/, '');
  const config = JSON.parse(read(`emails/${file}`));
  for (const key of ['direction', 'subject', 'body']) if (!config[key]) throw Error(`emails/${file} needs "${key}"`);
  if (!LAYOUTS[config.direction]) throw Error(`emails/${file}: direction must be outbound or inbound`);
  if (config.direction === 'inbound' && !config.header_label) throw Error(`emails/${file}: inbound emails need "header_label"`);
  EMAILS[name] = { direction: config.direction, subject: config.subject, preheader: config.preheader || '', header_label: config.header_label || '', footer_note: config.footer_note || '', body: config.body };
  SAMPLES[name] = config.sample || {};
}

const out = `// Generated by scripts/build-emails.mjs from docs/email-templates. Do not edit; edit the docs and re-run it.\nexport const LAYOUTS = ${JSON.stringify(LAYOUTS, null, 2)};\nexport const EMAILS = ${JSON.stringify(EMAILS, null, 2)};\n`;
const target = join(root, 'backend', 'emails.generated.js');
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== out) throw Error('backend/emails.generated.js is stale. Run node scripts/build-emails.mjs.');
} else {
  writeFileSync(target, out);
  console.log(`Wrote ${Object.keys(EMAILS).length} emails to backend/emails.generated.js.`);
}

if (process.argv.includes('--previews')) {
  const { render } = await import(pathToFileURL(join(root, 'backend', 'mailer.js')).href);
  const env = { SITE_URL: process.env.SITE_URL || 'https://vftech.io' };
  const dir = join(docs, 'previews');
  mkdirSync(dir, { recursive: true });
  let failed = false;
  for (const name of Object.keys(EMAILS)) {
    const email = render(name, SAMPLES[name], env, new Date('2026-11-17T15:04:00Z'));
    const all = `${email.subject}\n${email.html}\n${email.text}`;
    const leftover = [...new Set(all.match(/\{\{[#/]?\w+\}\}/g) || [])];
    if (leftover.length) { failed = true; console.error(`${name}: unfilled ${leftover.join(', ')}`); }
    if (/undefined|\bnull\b/.test(`${email.subject}\n${email.text}`)) { failed = true; console.error(`${name}: "undefined" or "null" in the text`); }
    if (/<b>test<\/b>/.test(email.html)) { failed = true; console.error(`${name}: typed HTML was not escaped`); }
    if (email.subject.length > 60) console.warn(`${name}: subject is ${email.subject.length} characters (aim for under 60)`);
    writeFileSync(join(dir, `${name}.html`), `<!-- Subject: ${email.subject.replace(/--/g, '- -')} -->\n${email.html}\n`);
    writeFileSync(join(dir, `${name}.txt`), `Subject: ${email.subject}\n\n${email.text}\n`);
  }
  console.log(`Rendered ${Object.keys(EMAILS).length} previews into docs/email-templates/previews.`);
  if (failed) process.exit(1);
}
